// Pseudo-code sketch
let model = initStreamingPCA(k=10);
for (let event of stream) {
  let x = imputeAndScale(event.features);
  let z = model.transform(x);
  driftMonitor.update(model.loadings);
  if (driftMonitor.alert) alert(z, driftMonitor.threshold);
  model.updateIfNeeded(x);
}
```

